import React, { useEffect, useState, useRef } from 'react';
import axios from 'axios';

const API_URL = 'http://localhost:8080/api/blogs';

const App = () => {
  const [blogs, setBlogs] = useState([]);
  const [title, setTitle] = useState('');
  const [content, setContent] = useState('');
  const [author, setAuthor] = useState('');
  const [category, setCategory] = useState('');
  const commentRefs = useRef({});

  useEffect(() => {
    fetchBlogs();
  }, []);

  const fetchBlogs = async () => {
    const response = await axios.get(API_URL);
    setBlogs(response.data);
  };

  const addBlog = async () => {
    const newBlog = { title, content, author, category };
    await axios.post(API_URL, newBlog);
    fetchBlogs();
    setTitle('');
    setContent('');
    setAuthor('');
    setCategory('');
  };

  const likeBlog = async (id) => {
    await axios.post(`${API_URL}/${id}/like`);
    fetchBlogs();
  };

  const addComment = async (id) => {
    const comment = commentRefs.current[id]?.value;
    if (comment) {
      await axios.post(`${API_URL}/${id}/comments`, { text: comment });
      fetchBlogs();
      commentRefs.current[id].value = '';
    }
  };

  return (
    <div className="p-6 bg-gray-100 min-h-screen">
      <div className="max-w-4xl mx-auto bg-white p-6 rounded shadow-md">
        <h1 className="text-2xl font-bold mb-4">Blog Application</h1>
        {/* Create Blog Form */}
        <div className="space-y-4 mb-6">
          <input
            type="text"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder="Title"
            className="w-full p-2 border rounded"
          />
          <textarea
            value={content}
            onChange={(e) => setContent(e.target.value)}
            placeholder="Content"
            className="w-full p-2 border rounded"
          />
          <input
            type="text"
            value={author}
            onChange={(e) => setAuthor(e.target.value)}
            placeholder="Author"
            className="w-full p-2 border rounded"
          />
          <input
            type="text"
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            placeholder="Category"
            className="w-full p-2 border rounded"
          />
          <button
            onClick={addBlog}
            className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
          >
            Add Blog
          </button>
        </div>

        {/* Display Blogs */}
        {blogs.map((blog) => (
          <div key={blog.id} className="border-t pt-4 mt-4">
            <h2 className="text-xl font-bold">{blog.title}</h2>
            <p>{blog.content}</p>
            <p className="text-gray-500">By {blog.author} - {blog.category}</p>
            <div className="flex items-center mt-2">
              <button
                onClick={() => likeBlog(blog.id)}
                className="mr-4 bg-red-500 text-white px-3 py-1 rounded"
              >
                ❤️ {blog.likes}
              </button>
              <input
                type="text"
                placeholder="Add a comment"
                ref={(el) => (commentRefs.current[blog.id] = el)}
                className="p-2 border rounded w-full"
              />
              <button
                onClick={() => addComment(blog.id)}
                className="ml-2 bg-green-500 text-white px-3 py-1 rounded"
              >
                Comment
              </button>
            </div>
            {/* Display Comments */}
            <div className="mt-2">
              {blog.comments.map((comment, index) => (
                <div key={index} className="text-gray-700">
                  • {comment.text}
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default App;
